/* From Uiverse.io by Df12345677 - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  gap: 10px;
}

.__UIV_SCOPE__ .loader span {
  height: 20px;
  width: 20px;
  background-image: linear-gradient(to right , #333 , #233,#222,#122,#112,#111,#011,#001,#000);
  border-radius: 50%;
  animation-name: animar;
  animation-duration: 3s;
  animation-iteration-count: infinite;
  box-shadow: 20px 20px 18px #666666,
             -20px -20px 18px #ffffff;
}

.__UIV_SCOPE__ #one {
  animation-delay: 1s;
}

.__UIV_SCOPE__ #two {
  animation-delay: 2s;
}

.__UIV_SCOPE__ #three {
  animation-delay: 3s;
}

@keyframes animar {
  0% {
    transform: scale(1);
  }

  33% {
    transform: scale(.3);
  }

  66% {
    transform: scale(1);
  }

  100% {
    transform: scale(1);
  }
}
